	CONSTRAINT "payroll_leave_valuations_source_check" CHECK ("payroll_leave_valuations"."source" IN ('time-off', 'exit')),
	CONSTRAINT "payroll_leave_valuations_amounts_check" CHECK ("payroll_leave_valuations"."days" > 0 AND "payroll_leave_valuations"."daily_rate" >= 0 AND "payroll_leave_valuations"."ends_on" >= "payroll_leave_valuations"."starts_on")
);
